    skin: pick(rng, ['#e8b88a', '#c98d5a', '#8a5a3a', '#f0c8a0']),
    hp: 30,
    state: 'walk', // walk | flee
    fleeX: 0, fleeY: 0,
    wanderT: range(rng, 2, 6),
